import * as fs from 'fs';

const logFile = '<tmp>';
const content = fs.readFileSync(logFile, 'utf-8');
const lines = content.split('\n').filter(line => line.trim() !== '');

interface LogEntry {
  timestamp: string;
  level: string;
  component: string;
  message: string;
}

const entries: LogEntry[] = [];

const regex = /^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

for (const line of lines) {
  const match = line.match(regex);
  if (match) {
    entries.push({
      timestamp: match[1],
      level: match[2],
      component: match[3],
      message: match[4],
    });
  }
}

const levelCounts: Map<string, number> = new Map();
for (const e of entries) {
  levelCounts.set(e.level, (levelCounts.get(e.level) || 0) + 1);
}

const errorComponentCounts: Map<string, number> = new Map();
for (const e of entries) {
  if (e.level === 'ERROR') {
    errorComponentCounts.set(e.component, (errorComponentCounts.get(e.component) || 0) + 1);
  }
}

const errorMessages: Set<string> = new Set();
for (const e of entries) {
  if (e.level === 'ERROR') {
    errorMessages.add(e.message);
  }
}

const hourCounts: Map<string, number> = new Map();
for (const e of entries) {
  const hour = e.timestamp.substring(11, 13);
  hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);
}

const out: string[] = [];
out.push('=== Log Analysis ===');
out.push('');
out.push('Entries by Level:');
const sortedLevels = [...levelCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [level, count] of sortedLevels) {
  out.push(`  ${level}: ${count}`);
}
out.push('');

let maxErrorComponent = '';
let maxErrorCount = 0;
for (const [comp, count] of errorComponentCounts) {
  if (count > maxErrorCount) {
    maxErrorCount = count;
    maxErrorComponent = comp;
  }
}
out.push(`Component with Most Errors: ${maxErrorComponent} (${maxErrorCount} errors)`);
out.push('');

out.push('Unique Error Messages:');
const sortedMessages = [...errorMessages].sort();
for (const msg of sortedMessages) {
  out.push(`  - ${msg}`);
}
out.push('');

let busiestHour = '';
let busiestCount = 0;
for (const [hour, count] of hourCounts) {
  if (count > busiestCount) {
    busiestCount = count;
    busiestHour = hour;
  }
}
out.push(`Busiest Hour: ${busiestHour}:00 (${busiestCount} entries)`);

process.stdout.write(out.join('\n') + '\n');

