import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String> lines;
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            lines = br.lines().collect(Collectors.toList());
        }

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        String highestName = "";
        double highestSalary = Double.NEGATIVE_INFINITY;
        double totalBudget = 0;

        for (int i = 1; i < lines.size(); i++) {
            String line = lines.get(i).trim();
            if (line.isEmpty()) continue;

            String[] parts = line.split(",");
            String name = parts[1].trim();
            String department = parts[2].trim();
            double salary = Double.parseDouble(parts[3].trim());

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }

            totalBudget += salary;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Salary Report ===\n");
        sb.append("\n");
        sb.append("Average Salary by Department:\n");

        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            String dept = entry.getKey();
            List<Double> salaries = entry.getValue();
            double avg = salaries.stream().mapToDouble(Double::doubleValue).average().orElse(0);
            sb.append(String.format("  %s: $%,.2f\n", dept, avg));
        }

        sb.append("\n");
        sb.append(String.format("Highest Paid: %s ($%,d)\n", highestName, Math.round(highestSalary)));
        sb.append("\n");
        sb.append("Departments with >2 employees:\n");

        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            if (entry.getValue().size() > 2) {
                sb.append(String.format("  %s (%d employees)\n", entry.getKey(), entry.getValue().size()));
            }
        }

        sb.append("\n");
        sb.append(String.format("Total Budget: $%,d\n", Math.round(totalBudget)));

        System.out.print(sb.toString());
    }
}

