import Foundation

let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    exit(1)
}

let lines = content.components(separatedBy: .newlines).filter { !$0.isEmpty }

var levelCounts: [String: Int] = [:]
var componentErrors: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

let pattern = "^\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2})\\] (\\S+) \\(([^)]+)\\) - (.+)$"
guard let regex = try? NSRegularExpression(pattern: pattern) else {
    exit(1)
}

for line in lines {
    let range = NSRange(line.startIndex..<line.endIndex, in: line)
    guard let match = regex.firstMatch(in: line, range: range) else { continue }

    let hourRange = match.range(at: 2)
    let hourStr = String(line[Range(hourRange, in: line)!])
    let hour = Int(hourStr) ?? 0

    let levelRange = match.range(at: 3)
    let level = String(line[Range(levelRange, in: line)!])

    let compRange = match.range(at: 4)
    let component = String(line[Range(compRange, in: line)!])

    let msgRange = match.range(at: 5)
    let message = String(line[Range(msgRange, in: line)!])

    levelCounts[level, default: 0] += 1
    hourCounts[hour, default: 0] += 1

    if level == "ERROR" {
        componentErrors[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for (level, count) in levelCounts.sorted(by: { $0.key < $1.key }) {
    print("  \(level): \(count)")
}
print("")

if let (comp, errCount) = componentErrors.max(by: { $0.value < $1.value }) {
    print("Component with Most Errors: \(comp) (\(errCount) errors)")
}
print("")

print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}
print("")

if let (hour, count) = hourCounts.max(by: { $0.value < $1.value }) {
    print("Busiest Hour: \(String(format: "%02d", hour)):00 (\(count) entries)")
}

