use std::fs;
use std::collections::BTreeMap;

fn format_int_with_commas(n: u64) -> String {
    let s = n.to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn format_decimal_with_commas(val: f64) -> String {
    let rounded = (val * 100.0).round() / 100.0;
    let int_part = rounded as u64;
    let dec_part = ((rounded - int_part as f64) * 100.0).round() as u64;
    let int_str = format_int_with_commas(int_part);
    format!("{}.{}", int_str, format!("{:02}", dec_part))
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let lines: Vec<&str> = content.lines().collect();

    let mut dept_salaries: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    let mut highest_name = String::new();
    let mut highest_salary: f64 = 0.0;
    let mut total_budget: f64 = 0.0;

    for line in lines.iter().skip(1) {
        if line.trim().is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].trim().to_string();
        let department = fields[2].trim().to_string();
        let salary: f64 = fields[3].trim().parse().expect("Failed to parse salary");

        dept_salaries.entry(department).or_insert_with(Vec::new).push(salary);
        total_budget += salary;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, salaries) in &dept_salaries {
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        println!("  {}: ${}", dept, format_decimal_with_commas(avg));
    }
    println!();
    println!("Highest Paid: {} (${})", highest_name, format_int_with_commas(highest_salary.round() as u64));
    println!();
    println!("Departments with >2 employees:");
    for (dept, salaries) in &dept_salaries {
        if salaries.len() > 2 {
            println!("  {} ({} employees)", dept, salaries.len());
        }
    }
    println!();
    println!("Total Budget: ${}", format_int_with_commas(total_budget.round() as u64));
}

