typedef struct {
    char name[512];
    char department[512];
    double salary;
} Employee;

typedef struct {
    char name[512];
    double total;
    int count;
} Dept;

static int cmp_dept(const void *a, const void *b) {
    return strcmp(((const Dept *)a)->name, ((const Dept *)b)->name);
}

static void format_commas(long val, char *buf, size_t size) {
    char digits[32];
    int len = snprintf(digits, sizeof(digits), "%ld", val);
    int out_len = 0;
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0) {
            if ((size_t)out_len + 1 < size) buf[out_len++] = ',';
        }
        if ((size_t)out_len + 1 < size) buf[out_len++] = digits[i];
    }
    buf[out_len] = '\0';
}

int main(void) {
    const char *filepath = "<tmp>";

    FILE *f = fopen(filepath, "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    char *line = malloc(8192);
    if (!line) { fclose(f); return 1; }

    /* Skip header */
    if (!fgets(line, 8192, f)) { free(line); fclose(f); return 1; }

    Employee *emps = NULL;
    int n_emps = 0, cap_emps = 0;

    while (fgets(line, 8192, f)) {
        size_t ll = strlen(line);
        while (ll > 0 && (line[ll - 1] == '\n' || line[ll - 1] == '\r')) line[--ll] = '\0';
        if (ll == 0) continue;

        if (n_emps >= cap_emps) {
            cap_emps = cap_emps ? cap_emps * 2 : 64;
            emps = realloc(emps, (size_t)cap_emps * sizeof(Employee));
            if (!emps) { free(line); fclose(f); return 1; }
        }

        /* Parse 6 comma-separated fields */
        char *fields[6];
        char *p = line;
        for (int i = 0; i < 6; i++) {
            fields[i] = p;
            char *comma = strchr(p, ',');
            if (comma) { *comma = '\0'; p = comma + 1; }
            else { p += strlen(p); }
        }

        strncpy(emps[n_emps].name, fields[1], 511);
        emps[n_emps].name[511] = '\0';
        strncpy(emps[n_emps].department, fields[2], 511);
        emps[n_emps].department[511] = '\0';
        emps[n_emps].salary = atof(fields[3]);
        n_emps++;
    }

    free(line);
    fclose(f);

    /* Build department aggregates */
    Dept *depts = NULL;
    int n_depts = 0, cap_depts = 0;

