        }
        if ((size_t)out_len + 1 < size) buf[out_len++] = digits[i];
    }
    buf[out_len] = '\0';
}

int main(void) {
    const char *filepath = "<tmp>";

    FILE *f = fopen(filepath, "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    char *line = malloc(8192);
    if (!line) { fclose(f); return 1; }

    /* Skip header */
    if (!fgets(line, 8192, f)) { free(line); fclose(f); return 1; }

    Employee *emps = NULL;
    int n_emps = 0, cap_emps = 0;

    while (fgets(line, 8192, f)) {
        size_t ll = strlen(line);
        while (ll > 0 && (line[ll - 1] == '\n' || line[ll - 1] == '\r')) line[--ll] = '\0';
        if (ll == 0) continue;

        if (n_emps >= cap_emps) {
            cap_emps = cap_emps ? cap_emps * 2 : 64;
            emps = realloc(emps, (size_t)cap_emps * sizeof(Employee));
            if (!emps) { free(line); fclose(f); return 1; }
        }

        /* Parse 6 comma-separated fields */
        char *fields[6];
        char *p = line;
        for (int i = 0; i < 6; i++) {
            fields[i] = p;
            char *comma = strchr(p, ',');
            if (comma) { *comma = '\0'; p = comma + 1; }
            else { p += strlen(p); }
        }

        strncpy(emps[n_emps].name, fields[1], 511);
        emps[n_emps].name[511] = '\0';
        strncpy(emps[n_emps].department, fields[2], 511);
        emps[n_emps].department[511] = '\0';
        emps[n_emps].salary = atof(fields[3]);
        n_emps++;
    }

    free(line);
    fclose(f);

    /* Build department aggregates */
    Dept *depts = NULL;
    int n_depts = 0, cap_depts = 0;

    for (int i = 0; i < n_emps; i++) {
        int found = -1;
        for (int j = 0; j < n_depts; j++) {
            if (strcmp(depts[j].name, emps[i].department) == 0) { found = j; break; }
        }
        if (found >= 0) {
            depts[found].total += emps[i].salary;
            depts[found].count++;
        } else {
            if (n_depts >= cap_depts) {
                cap_depts = cap_depts ? cap_depts * 2 : 32;
                depts = realloc(depts, (size_t)cap_depts * sizeof(Dept));
                if (!depts) { free(emps); return 1; }
            }
            strncpy(depts[n_depts].name, emps[i].department, 511);
            depts[n_depts].name[511] = '\0';
            depts[n_depts].total = emps[i].salary;
            depts[n_depts].count = 1;
            n_depts++;
        }
    }

    qsort(depts, (size_t)n_depts, sizeof(Dept), cmp_dept);

    /* Highest paid */
    int hi = 0;
    for (int i = 1; i < n_emps; i++) {
        if (emps[i].salary > emps[hi].salary) hi = i;
    }

    /* Total budget */
    double total_sum = 0.0;
    for (int i = 0; i < n_emps; i++) total_sum += emps[i].salary;
    long total_budget = (long)(total_sum + 0.5);

    /* Output */
    char buf[128];

    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < n_depts; i++) {
        double avg = depts[i].total / (double)depts[i].count;
        long ipart = (long)avg;
        long frac = (long)((avg - (double)ipart) * 100.0 + 0.5);
        if (frac >= 100) { ipart++; frac -= 100; }
        if (frac < 0) { ipart--; frac += 100; }
        format_commas(ipart, buf, sizeof(buf));
        printf("  %s: $%s.%02ld\n", depts[i].name, buf, frac);
    }
    printf("\n");
    printf("Highest Paid: %s ($", emps[hi].name);
    format_commas((long)(emps[hi].salary + 0.5), buf, sizeof(buf));
    printf("%s)\n", buf);
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < n_depts; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");
    printf("Total Budget: $");
    format_commas(total_budget, buf, sizeof(buf));
    printf("%s\n", buf);

    free(emps);
    free(depts);
    return 0;
}
