use std::fs;
use std::collections::HashMap;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut error_component_counts: HashMap<String, usize> = HashMap::new();
    let mut error_messages: Vec<String> = Vec::new();
    let mut hour_counts: HashMap<u32, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let bracket_end = line.find(']').expect("No closing bracket");
        let timestamp = &line[1..bracket_end];

        let after_bracket = &line[bracket_end + 2..];

        let paren_start = after_bracket.find(" (").expect("No component paren");
        let level = &after_bracket[..paren_start];

        let after_paren_start = paren_start + 2;
        let paren_end = after_bracket[after_paren_start..]
            .find(')')
            .expect("No closing paren");
        let component = &after_bracket[after_paren_start..after_paren_start + paren_end];

        let message = &after_bracket[after_paren_start + paren_end + 4..];

        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts
                .entry(component.to_string())
                .or_insert(0) += 1;
            error_messages.push(message.to_string());
        }

        let hour_str = &timestamp[11..13];
        let hour: u32 = hour_str.parse().expect("Invalid hour");
        *hour_counts.entry(hour).or_insert(0) += 1;
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    let mut sorted_levels: Vec<&String> = level_counts.keys().collect();
    sorted_levels.sort();
    for level in sorted_levels {
        println!("  {}: {}", level, level_counts[level]);
    }
    println!();

    let (top_component, top_count) = error_component_counts
        .iter()
        .max_by_key(|(_, count)| count)
        .expect("No errors found");
    println!(
        "Component with Most Errors: {} ({} errors)",
        top_component, top_count
    );
    println!();

    println!("Unique Error Messages:");
    let mut unique_msgs: Vec<&String> = error_messages.iter().collect();
    unique_msgs.sort();
    unique_msgs.dedup();
    for msg in unique_msgs {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, count)| count)
        .expect("No entries");
    println!(
        "Busiest Hour: {:02}:00 ({} entries)",
        busiest_hour, busiest_count
    );
}

