import java.io.*;
import java.util.*;
import java.nio.file.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String path = "<tmp>";
        String json = new String(Files.readAllBytes(Paths.get(path)));

        // Parse nodes
        List<String> nodes = new ArrayList<>();
        int nodesKey = json.indexOf("\"nodes\"");
        int bracketStart = json.indexOf('[', nodesKey);
        int bracketEnd = json.indexOf(']', bracketStart);
        String nodesStr = json.substring(bracketStart + 1, bracketEnd);
        for (String s : nodesStr.split(",")) {
            s = s.trim();
            if (s.startsWith("\"") && s.endsWith("\"")) {
                nodes.add(s.substring(1, s.length() - 1));
            }
        }

        // Parse edges
        List<String> froms = new ArrayList<>();
        List<String> tos = new ArrayList<>();
        List<Long> weights = new ArrayList<>();

        int edgesKey = json.indexOf("\"edges\"");
        int eBracketStart = json.indexOf('[', edgesKey);
        int depth = 0;
        int eBracketEnd = -1;
        for (int i = eBracketStart; i < json.length(); i++) {
            if (json.charAt(i) == '[') depth++;
            if (json.charAt(i) == ']') {
                depth--;
                if (depth == 0) { eBracketEnd = i; break; }
            }
        }
        String edgesStr = json.substring(eBracketStart + 1, eBracketEnd);

        int pos = 0;
        while (pos < edgesStr.length()) {
            int objStart = edgesStr.indexOf('{', pos);
            if (objStart == -1) break;
            int objEnd = edgesStr.indexOf('}', objStart);
            String obj = edgesStr.substring(objStart, objEnd + 1);

            int fromIdx = obj.indexOf("\"from\"");
            int colonIdx = obj.indexOf(':', fromIdx);
            int qStart = obj.indexOf('"', colonIdx);
            int qEnd = obj.indexOf('"', qStart + 1);
            String from = obj.substring(qStart + 1, qEnd);

            int toIdx = obj.indexOf("\"to\"");
            colonIdx = obj.indexOf(':', toIdx);
            qStart = obj.indexOf('"', colonIdx);
            qEnd = obj.indexOf('"', qStart + 1);
            String to = obj.substring(qStart + 1, qEnd);

            int wIdx = obj.indexOf("\"weight\"");
            colonIdx = obj.indexOf(':', wIdx);
            int numStart = colonIdx + 1;
            while (numStart < obj.length() && obj.charAt(numStart) == ' ') numStart++;
            int numEnd = numStart;
            while (numEnd < obj.length() && (Character.isDigit(obj.charAt(numEnd)) || obj.charAt(numEnd) == '-')) numEnd++;
            long weight = Long.parseLong(obj.substring(numStart, numEnd));

            froms.add(from);
            tos.add(to);
            weights.add(weight);

            pos = objEnd + 1;
        }

        // Build adjacency list (undirected)
        Map<String, List<String[]>> adj = new HashMap<>();
        for (String n : nodes) adj.put(n, new ArrayList<>());
        for (int i = 0; i < froms.size(); i++) {
            adj.get(froms.get(i)).add(new String[]{tos.get(i), String.valueOf(weights.get(i))});
            adj.get(tos.get(i)).add(new String[]{froms.get(i), String.valueOf(weights.get(i))});
        }

        // Dijkstra's algorithm from "A"
        Map<String, Long> dist = new HashMap<>();
        for (String n : nodes) dist.put(n, Long.MAX_VALUE);
        dist.put("A", 0L);

        PriorityQueue<Object[]> pq = new PriorityQueue<>((a, b) -> Long.compare((Long) a[1], (Long) b[1]));
        pq.add(new Object[]{"A", 0L});

        while (!pq.isEmpty()) {
            Object[] curr = pq.poll();
            String u = (String) curr[0];
            long d = (Long) curr[1];
            if (d > dist.get(u)) continue;
            for (String[] edge : adj.get(u)) {
                String v = edge[0];
                long w = Long.parseLong(edge[1]);
                if (dist.get(u) + w < dist.get(v)) {
                    dist.put(v, dist.get(u) + w);
                    pq.add(new Object[]{v, dist.get(v)});
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);
        for (String n : sorted) {
            System.out.println("A -> " + n + ": " + dist.get(n));
        }
    }
}

