                                        low = low * 16 + c.to_digit(16).unwrap();
                                    }
                                    let cp = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                    s.push(char::from_u32(cp).unwrap());
                                }
                            }
                        } else {
                            s.push(char::from_u32(code).unwrap());
                        }
                    }
                    _ => {}
                },
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' || c.is_ascii_digit() {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        Json::Number(s.parse::<f64>().unwrap())
    }

    fn parse_array(&mut self) -> Json {
        self.advance(); // consume [
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.advance();
            return Json::Array(arr);
        }
        loop {
            let val = self.parse_value();
            arr.push(val);
            self.skip_whitespace();
            match self.advance() {
                Some(',') => continue,
                Some(']') => break,
                _ => break,
            }
        }
        Json::Array(arr)
    }

    fn parse_object(&mut self) -> Json {
        self.advance(); // consume {
        let mut obj = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.advance();
            return Json::Object(obj);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.advance(); // consume :
            let val = self.parse_value();
            obj.insert(key, val);
            self.skip_whitespace();
            match self.advance() {
                Some(',') => continue,
                Some('}') => break,
                _ => break,
            }
        }
        Json::Object(obj)
    }
}

fn deep_merge(a: &Json, b: &Json) -> Json {
    match (a, b) {
        (Json::Object(a_map), Json::Object(b_map)) => {
            let mut result = BTreeMap::new();
            for (k, v) in a_map {
                result.insert(k.clone(), v.clone());
            }
            for (k, v) in b_map {
                if let Some(existing) = result.get(k) {
                    result.insert(k.clone(), deep_merge(existing, v));
                } else {
                    result.insert(k.clone(), v.clone());
                }
            }
            Json::Object(result)
        }
        (Json::Array(a_arr), Json::Array(b_arr)) => {
            let mut result: Vec<Json> = a_arr.clone();
            for item in b_arr {
                if !result.contains(item) {
                    result.push(item.clone());
                }
            }
            Json::Array(result)
        }
        (_, b) => b.clone(),
    }
}

fn format_number(n: f64) -> String {
    if n == n.floor() && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn format_string(s: &str) -> String {
    let mut result = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result.push('"');
    result
}

fn serialize(value: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);
    match value {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => format_number(*n),
        Json::String(s) => format_string(s),
        Json::Array(arr) => {
            if arr.is_empty() {
                "[]".to_string()
            } else {
                let mut parts = Vec::new();
                for item in arr {
                    parts.push(format!("{}{}", pad_inner, serialize(item, indent + 1)));
                }
                format!("[\n{}\n{}]", parts.join(",\n"), pad)
            }
        }
        Json::Object(obj) => {
            if obj.is_empty() {
                "{}".to_string()
            } else {
                let mut parts = Vec::new();
                for (k, v) in obj {
                    parts.push(format!(
                        "{}{}: {}",
                        pad_inner,
                        format_string(k),
                        serialize(v, indent + 1)
                    ));
                }
                format!("{{\n{}\n{}}}", parts.join(",\n"), pad)
            }
        }
    }
}

fn main() {
    let a_str = fs::read_to_string(
        "<tmp>",
    )
    .expect("Failed to read config_a.json");
    let b_str = fs::read_to_string(
        "<tmp>",
    )
    .expect("Failed to read config_b.json");

    let a = Parser::new(&a_str).parse();
    let b = Parser::new(&b_str).parse();

    let merged = deep_merge(&a, &b);

    println!("{}", serialize(&merged, 0));
}

