import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileEntry {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(buffer: Buffer): number {
  if (buffer.length === 0) return 0;
  let count = 0;
  for (let i = 0; i < buffer.length; i++) {
    if (buffer[i] === 10) count++;
  }
  if (buffer[buffer.length - 1] !== 10) count++;
  return count;
}

function walkDir(currentDir: string, result: Map<string, FileEntry[]>, visitedDirs: Set<string>): void {
  const resolved = fs.realpathSync(currentDir);
  if (visitedDirs.has(resolved)) return;
  visitedDirs.add(resolved);

  const entries = fs.readdirSync(currentDir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(currentDir, entry.name);
    if (entry.isDirectory()) {
      walkDir(fullPath, result, visitedDirs);
    } else if (entry.isFile()) {
      const buffer = fs.readFileSync(fullPath);
      const lines = countLines(buffer);
      const chars = buffer.length;
      const relativePath = path.relative(rootDir, fullPath).split(path.sep).join('/');
      const ext = path.extname(entry.name);
      if (!result.has(ext)) {
        result.set(ext, []);
      }
      result.get(ext)!.push({ relativePath, lines, chars });
    }
  }
}

const groups = new Map<string, FileEntry[]>();
const visitedDirs = new Set<string>();
walkDir(rootDir, groups, visitedDirs);

