out.push('=== File Tree Analysis ===');
out.push('');

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of sortedExts) {
  const files = groups.get(ext)!.sort((a, b) => a.relativePath.localeCompare(b.relativePath));
  const extTotalLines = files.reduce((s, f) => s + f.lines, 0);
  const extTotalChars = files.reduce((s, f) => s + f.chars, 0);

  out.push(`Extension: ${ext}`);
