import Foundation

let rootPath = "<tmp>"
let fileManager = FileManager.default

struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
    let ext: String
}

var allFiles: [FileInfo] = []
var visitedDirs: Set<String> = []

func walk(_ path: String) {
    let resolved = (path as NSString).resolvingSymlinksInPath
    if visitedDirs.contains(resolved) { return }
    visitedDirs.insert(resolved)

    guard let contents = try? fileManager.contentsOfDirectory(atPath: path) else { return }

    for name in contents {
        let fullPath = path + "/" + name

        let attrs = try? fileManager.attributesOfItem(atPath: fullPath)
        guard let attrs = attrs else { continue }

        if let type = attrs[.type] as? FileAttributeType {
            if type == .typeSymbolicLink { continue }
        }

        let isDir: Bool
        if let type = attrs[.type] as? FileAttributeType {
            isDir = (type == .typeDirectory)
        } else {
            var isDirVar: ObjCBool = false
            fileManager.fileExists(atPath: fullPath, isDirectory: &isDirVar)
            isDir = isDirVar.boolValue
        }

        if isDir {
            walk(fullPath)
        } else {
            let relativePath = String(fullPath.dropFirst(rootPath.count + 1))

            guard let data = try? Data(contentsOf: URL(fileURLWithPath: fullPath)) else { continue }

            let chars = data.count
            let content = String(data: data, encoding: .utf8) ?? ""

            let lines: Int
            if content.isEmpty {
                lines = 0
            } else {
                var parts = content.components(separatedBy: "\n")
                if parts.last == "" {
                    parts.removeLast()
                }
                lines = parts.count
            }

            let ext = (fullPath as NSString).pathExtension
            let extStr = ext.isEmpty ? "" : "." + ext

            allFiles.append(FileInfo(relativePath: relativePath, lines: lines, chars: chars, ext: extStr))
        }
    }
}

