use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

fn main() {
    let root = Path::new("<tmp>");

    let mut files: Vec<(String, u64, u64)> = Vec::new();
    walk_dir(root, root, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();
    for (rel_path, lines, chars) in &files {
        let ext = get_extension(rel_path);
        groups.entry(ext).or_default().push((rel_path.clone(), *lines, *chars));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut total_chars: u64 = 0;

    for (ext, file_list) in &groups {
        let n_files = file_list.len() as u64;
        let n_lines: u64 = file_list.iter().map(|f| f.1).sum();
        let n_chars: u64 = file_list.iter().map(|f| f.2).sum();

        total_files += n_files;
        total_lines += n_lines;
        total_chars += n_chars;

        println!("Extension: {}", ext);
        println!("  Files: {}", n_files);
        println!("  Total Lines: {}", n_lines);
        println!("  Total Characters: {}", n_chars);
        for (path, lines, chars) in file_list {
            println!("    {}: {} lines, {} chars", path, lines, chars);
        }
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

fn walk_dir(root: &Path, dir: &Path, files: &mut Vec<(String, u64, u64)>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let ft = match entry.file_type() {
            Ok(t) => t,
            Err(_) => continue,
        };

        if ft.is_symlink() {
            continue;
        }

        let path = entry.path();

        if ft.is_dir() {
            walk_dir(root, &path, files);
        } else if ft.is_file() {
            let rel_path = path
                .strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/");

            let (lines, chars) = count_file(&path);
            files.push((rel_path, lines, chars));
        }
    }
}

fn count_file(path: &Path) -> (u64, u64) {
    let mut contents = Vec::new();
    match fs::File::open(path) {
        Ok(mut f) => {
            if f.read_to_end(&mut contents).is_err() {
                return (0, 0);
            }
        }
        Err(_) => return (0, 0),
    }

    let chars = contents.len() as u64;
    let lines = if contents.is_empty() {
        0
    } else {
        let nl_count = contents.iter().filter(|&&b| b == b'\n').count() as u64;
        if contents[contents.len() - 1] == b'\n' {
            nl_count
        } else {
            nl_count + 1
        }
    };

    (lines, chars)
}

fn get_extension(path: &str) -> String {
    let filename = path.rsplit('/').next().unwrap_or(path);
    if let Some(dot_pos) = filename.rfind('.') {
        if dot_pos > 0 {
            format!(".{}", &filename[dot_pos + 1..])
        } else {
            String::new()
        }
    } else {
        String::new()
    }
}

