/* Deep equality */
static int json_equal(const JsonValue *a, const JsonValue *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->num_val == b->num_val;
        case JSON_STRING: return a->str_val && b->str_val && strcmp(a->str_val, b->str_val) == 0;
        case JSON_ARRAY: {
            if (a->item_count != b->item_count) return 0;
            for (int i = 0; i < a->item_count; i++) {
                if (!json_equal(a->items[i], b->items[i])) return 0;
            }
            return 1;
        }
        case JSON_OBJECT: {
            if (a->key_count != b->key_count) return 0;
            for (int i = 0; i < a->key_count; i++) {
                int found = 0;
                for (int j = 0; j < b->key_count; j++) {
                    if (strcmp(a->keys[i], b->keys[j]) == 0) {
                        if (!json_equal(a->values[i], b->values[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
        }
    }
    return 0;
}

