static JsonValue *deep_copy(const JsonValue *v) {
    if (!v) return NULL;
    JsonValue *c = json_new();
    c->type = v->type;
    c->bool_val = v->bool_val;
    c->num_val = v->num_val;
    if (v->str_val) c->str_val = str_dup(v->str_val);
    if (v->type == JSON_ARRAY) {
        c->item_count = v->item_count;
        if (v->item_count > 0) {
            c->items = (JsonValue **)malloc(v->item_count * sizeof(JsonValue *));
            for (int i = 0; i < v->item_count; i++)
                c->items[i] = deep_copy(v->items[i]);
        }
    } else if (v->type == JSON_OBJECT) {
        c->key_count = v->key_count;
        if (v->key_count > 0) {
            c->keys = (char **)malloc(v->key_count * sizeof(char *));
            c->values = (JsonValue **)malloc(v->key_count * sizeof(JsonValue *));
            for (int i = 0; i < v->key_count; i++) {
                c->keys[i] = str_dup(v->keys[i]);
                c->values[i] = deep_copy(v->values[i]);
            }
        }
    }
    return c;
}

static JsonValue *deep_merge(const JsonValue *a, const JsonValue *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *result = json_new();
        result->type = JSON_OBJECT;
        int cap = a->key_count + b->key_count;
        if (cap < 4) cap = 4;
        result->keys = (char **)malloc(cap * sizeof(char *));
        result->values = (JsonValue **)malloc(cap * sizeof(JsonValue *));
        result->key_count = 0;

        for (int i = 0; i < a->key_count; i++) {
            int bi = find_key(b, a->keys[i]);
            if (bi >= 0) {
                if (result->key_count >= cap) {
                    cap *= 2;
                    result->keys = (char **)realloc(result->keys, cap * sizeof(char *));
                    result->values = (JsonValue **)realloc(result->values, cap * sizeof(JsonValue *));
                }
                result->keys[result->key_count] = str_dup(a->keys[i]);
                result->values[result->key_count] = deep_merge(a->values[i], b->values[bi]);
                result->key_count++;
            } else {
                if (result->key_count >= cap) {
                    cap *= 2;
                    result->keys = (char **)realloc(result->keys, cap * sizeof(char *));
                    result->values = (JsonValue **)realloc(result->values, cap * sizeof(JsonValue *));
                }
                result->keys[result->key_count] = str_dup(a->keys[i]);
                result->values[result->key_count] = deep_copy(a->values[i]);
                result->key_count++;
            }
        }

        for (int i = 0; i < b->key_count; i++) {
            if (find_key(a, b->keys[i]) < 0) {
                if (result->key_count >= cap) {
                    cap *= 2;
                    result->keys = (char **)realloc(result->keys, cap * sizeof(char *));
                    result->values = (JsonValue **)realloc(result->values, cap * sizeof(JsonValue *));
                }
                result->keys[result->key_count] = str_dup(b->keys[i]);
                result->values[result->key_count] = deep_copy(b->values[i]);
                result->key_count++;
            }
        }
        return result;
    }

    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *result = json_new();
        result->type = JSON_ARRAY;
        int cap = a->item_count + b->item_count;
        if (cap < 4) cap = 4;
        result->items = (JsonValue **)malloc(cap * sizeof(JsonValue *));
        result->item_count = 0;

        for (int i = 0; i < a->item_count; i++) {
            if (result->item_count >= cap) {
                cap *= 2;
                result->items = (JsonValue **)realloc(result->items, cap * sizeof(JsonValue *));
            }
            result->items[result->item_count++] = deep_copy(a->items[i]);
        }

        for (int i = 0; i < b->item_count; i++) {
            if (!array_contains(result, b->items[i])) {
                if (result->item_count >= cap) {
                    cap *= 2;
                    result->items = (JsonValue **)realloc(result->items, cap * sizeof(JsonValue *));
                }
                result->items[result->item_count++] = deep_copy(b->items[i]);
            }
        }
        return result;
    }

    return deep_copy(b);
}

static void sort_object_keys(JsonValue *obj) {
    int n = obj->key_count;
    if (n <= 1) return;
    for (int i = 1; i < n; i++) {
        for (int j = i; j > 0; j--) {
            if (strcmp(obj->keys[j], obj->keys[j-1]) < 0) {
                char *tk = obj->keys[j];
                obj->keys[j] = obj->keys[j-1];
                obj->keys[j-1] = tk;
                JsonValue *tv = obj->values[j];
                obj->values[j] = obj->values[j-1];
                obj->values[j-1] = tv;
            } else {
                break;
            }
        }
    }
}

static void sort_all(JsonValue *v) {
    if (!v) return;
    if (v->type == JSON_OBJECT) {
        sort_object_keys(v);
        for (int i = 0; i < v->key_count; i++) {
            sort_all(v->values[i]);
        }
    } else if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->item_count; i++) {
            sort_all(v->items[i]);
        }
    }
}

static void print_string_escaped(const char *s) {
    putchar('"');
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", stdout); break;
            case '\\': fputs("\\\\", stdout); break;
            case '\b': fputs("\\b", stdout); break;
            case '\f': fputs("\\f", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default:
                if (c < 0x20) {
                    printf("\\u%04x", c);
                } else {
                    putchar(c);
                }
                break;
        }
    }
    putchar('"');
}

static void print_value(const JsonValue *v, int depth) {
    int indent = depth * 2;
    switch (v->type) {
        case JSON_NULL:
            fputs("null", stdout);
            break;
        case JSON_BOOL:
            if (v->bool_val) fputs("true", stdout);
            else fputs("false", stdout);
            break;
        case JSON_NUMBER:
            fputs(v->str_val, stdout);
            break;
        case JSON_STRING:
            print_string_escaped(v->str_val);
            break;
        case JSON_ARRAY:
            if (v->item_count == 0) {
                fputs("[]", stdout);
            } else {
                putchar('[');
                putchar('\n');
                for (int i = 0; i < v->item_count; i++) {
                    for (int s = 0; s < (indent + 2); s++) putchar(' ');
                    print_value(v->items[i], depth + 1);
                    if (i < v->item_count - 1) putchar(',');
                    putchar('\n');
                }
                for (int s = 0; s < indent; s++) putchar(' ');
                putchar(']');
            }
            break;
        case JSON_OBJECT:
            if (v->key_count == 0) {
                fputs("{}", stdout);
            } else {
                putchar('{');
                putchar('\n');
                for (int i = 0; i < v->key_count; i++) {
                    for (int s = 0; s < (indent + 2); s++) putchar(' ');
                    print_string_escaped(v->keys[i]);
                    fputs(": ", stdout);
                    print_value(v->values[i], depth + 1);
                    if (i < v->key_count - 1) putchar(',');
                    putchar('\n');
                }
                for (int s = 0; s < indent; s++) putchar(' ');
                putchar('}');
            }
            break;
    }
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    char *file_a = read_file(path_a);
    char *file_b = read_file(path_b);

    JsonValue *a = parse_json(file_a, strlen(file_a));
    JsonValue *b = parse_json(file_b, strlen(file_b));

    free(file_a);
    free(file_b);

    JsonValue *merged = deep_merge(a, b);

    json_free(a);
    json_free(b);

    sort_all(merged);

    print_value(merged, 0);
    putchar('\n');

    json_free(merged);

